SELECT COUNT(*) FROM (
    WITH fund_outperformance AS (
        SELECT portfolioref, fundperf - categoryperf AS outperformance, categoryperf, CASE WHEN categoryperf > 0 THEN 'up' ELSE 'down' END AS market_condition FROM annual_returns WHERE fundperf IS NOT NULL AND categoryperf IS NOT NULL
    ),
    fund_stats AS (
        SELECT portfolioref, COUNT(*) as num_years, AVG(CASE WHEN market_condition = 'up' THEN outperformance END) AS avg_upside_outperformance, AVG(CASE WHEN market_condition = 'down' THEN outperformance END) AS avg_downside_outperformance FROM fund_outperformance GROUP BY portfolioref HAVING COUNT(*) >= 7
    )
    SELECT * FROM fund_stats
) sub;

